package com.yuyutian.mytools.media.library.config;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.web.client.RestClient;import com.yuyutian.mytools.media.library.service.MediaTaskSchedulerClient;
/** Media Library 配置。 */ @Configuration public class MediaLibraryConfiguration { /** 创建事务模板。 @param manager 管理器 @return 模板 */ @Bean public TransactionTemplate transactions(PlatformTransactionManager manager){return new TransactionTemplate(manager);} /** 创建内部令牌。 @param value 值 @return 令牌 */ @Bean public InternalToken internalToken(@Value("${media-library.internal-token:}")String value){return new InternalToken(value);} /** 内部令牌。 */ public record InternalToken(String value){} /** 创建旧内容只读配置。 @param host 主机 @param port 端口 @param database 数据库 @param username 用户 @param password 密码 @return 配置 */ @Bean public LegacyContentDatabase legacyContentDatabase(@Value("${media-library.legacy-db-host:127.0.0.1}")String host,@Value("${media-library.legacy-db-port:3306}")int port,@Value("${media-library.legacy-db-name:mytools}")String database,@Value("${media-library.legacy-db-user:}")String username,@Value("${media-library.legacy-db-password:}")String password){return new LegacyContentDatabase(host,port,database,username,password);} /** 旧内容只读数据库配置。 */ public record LegacyContentDatabase(String host,int port,String database,String username,String password){} /** 创建调度客户端。 @param builder 构建器 @param url 地址 @return 客户端 */ @Bean public MediaTaskSchedulerClient schedulerClient(RestClient.Builder builder,@Value("${media-library.task-scheduler-url:http://127.0.0.1:23410}")String url){return new MediaTaskSchedulerClient(builder.baseUrl(url).build());} }
